/**
 * Creates a debounced function that delays invoking `func` until after `wait`
 * milliseconds have elapsed since the last time it was invoked.
 *
 * @param {Function} func - The function to debounce.
 * @param {number} wait - The number of milliseconds to delay.
 * @returns {Function} A debounced version of `func`.
 */
function debounce(func, wait) {
  let timeoutId;

  /**
   * Debounced wrapper function.
   *
   * @param {...any} args - Arguments passed through to the original function.
   * @returns {undefined}
   */
  return function (...args) {
    clearTimeout(timeoutId);

    timeoutId = setTimeout(() => {
      func.apply(this, args);
    }, wait);
  };
}

// Usage example:
const logMessage = debounce((message) => {
  console.log(message);
}, 1000);

logMessage('Hello');
logMessage('World'); // Only "World" will be logged after 1 second.
